#include "kernel.h"
#include "ap_fixed.h"

// ─────────────────────────────────────────────────────────────────────────────
// Internal high-precision fixed-point type for intermediate arithmetic.
// We use <48,24> → 24 integer bits, 24 fraction bits.
// ─────────────────────────────────────────────────────────────────────────────
typedef ap_fixed<48, 24> fx_t;

// ─────────────────────────────────────────────────────────────────────────────
// Compile-time constants
// ─────────────────────────────────────────────────────────────────────────────
static const int N = 10;

// Fixed-point π/2 and π
static const fx_t FX_PI      = fx_t(3.14159265358979323846);
static const fx_t FX_HALF_PI = fx_t(1.57079632679489661923);
static const fx_t FX_TWO_PI  = fx_t(6.28318530717958647692);
static const fx_t FX_ONE     = fx_t(1);
static const fx_t FX_ZERO    = fx_t(0);
static const fx_t FX_HALF    = fx_t(0.5);
static const fx_t FX_THRESH  = fx_t(1e-6);   // convergence threshold (fixed-pt friendly)

// ─────────────────────────────────────────────────────────────────────────────
// Integer square-root helper (Newton-Raphson, pure fixed-point)
// ─────────────────────────────────────────────────────────────────────────────
static fx_t fx_sqrt(fx_t x) {
#pragma HLS INLINE
    if (x <= FX_ZERO) return FX_ZERO;
    // Initial guess
    fx_t est = x * FX_HALF + FX_HALF;
    // 8 Newton iterations
    for (int i = 0; i < 8; ++i) {
#pragma HLS UNROLL
        fx_t denom = est;
        if (denom == FX_ZERO) denom = fx_t(1e-12);
        est = FX_HALF * (est + x / denom);
    }
    return est;
}

// ─────────────────────────────────────────────────────────────────────────────
// atan2 approximation using a minimax polynomial on [-1,1].
// Returns value in (-π, π].
// ─────────────────────────────────────────────────────────────────────────────
static fx_t fx_atan_unit(fx_t x) {
#pragma HLS INLINE
    // atan(x) ≈ x*(a0 + a2*x^2 + a4*x^4 + a6*x^6) for |x|<=1
    // Coefficients from Horner: atan(x)≈x*(0.9999993 - 0.3333131*x^2 + 0.1999591*x^2^2 - 0.1420889*x^2^3 + 0.1065626*x^2^4 - 0.0752896*x^2^5 + 0.0429096*x^2^6 - 0.0161657*x^2^7 + 0.0028662*x^2^8)
    fx_t x2 = x * x;
    fx_t p = fx_t(0.0028662);
    p = p * x2 - fx_t(0.0161657);
    p = p * x2 + fx_t(0.0429096);
    p = p * x2 - fx_t(0.0752896);
    p = p * x2 + fx_t(0.1065626);
    p = p * x2 - fx_t(0.1420889);
    p = p * x2 + fx_t(0.1999591);
    p = p * x2 - fx_t(0.3333131);
    p = p * x2 + fx_t(0.9999993);
    return x * p;
}

static fx_t fx_atan2(fx_t y, fx_t x) {
#pragma HLS INLINE
    fx_t abs_y = (y < FX_ZERO) ? -y : y;
    fx_t abs_x = (x < FX_ZERO) ? -x : x;
    fx_t angle;
    bool swap = abs_y > abs_x;
    fx_t num   = swap ? abs_x : abs_y;
    fx_t denom = swap ? abs_y : abs_x;
    if (denom == FX_ZERO) denom = fx_t(1e-12);
    fx_t r = num / denom;
    angle = fx_atan_unit(r);
    if (swap) angle = FX_HALF_PI - angle;
    if (x < FX_ZERO) angle = FX_PI - angle;
    if (y < FX_ZERO) angle = -angle;
    return angle;
}

// ─────────────────────────────────────────────────────────────────────────────
// arctan(v) for any v (not restricted to [-1,1])
// ─────────────────────────────────────────────────────────────────────────────
static fx_t fx_atan(fx_t v) {
#pragma HLS INLINE
    return fx_atan2(v, FX_ONE);
}

// ─────────────────────────────────────────────────────────────────────────────
// cos / sin via Taylor series (argument expected in (-π, π])
// ─────────────────────────────────────────────────────────────────────────────
static void fx_sincos(fx_t angle, fx_t &s, fx_t &c) {
#pragma HLS INLINE
    // Reduce to [-π, π]
    while (angle >  FX_PI)  angle = angle - FX_TWO_PI;
    while (angle < -FX_PI)  angle = angle + FX_TWO_PI;

    // Taylor: cos = 1 - x²/2 + x⁴/24 - x⁶/720 + x⁸/40320 - x¹⁰/3628800
    //         sin = x - x³/6 + x⁵/120 - x⁷/5040 + x⁹/362880
    fx_t x2 = angle * angle;
    fx_t x3 = x2 * angle;
    fx_t x5 = x3 * x2;
    fx_t x7 = x5 * x2;
    fx_t x9 = x7 * x2;
    fx_t x4 = x2 * x2;
    fx_t x6 = x4 * x2;
    fx_t x8 = x6 * x2;
    fx_t x10= x8 * x2;

    s = angle
      - x3  * fx_t(0.16666666667)
      + x5  * fx_t(0.00833333333)
      - x7  * fx_t(0.00019841270)
      + x9  * fx_t(0.00000275573);

    c = FX_ONE
      - x2  * fx_t(0.5)
      + x4  * fx_t(0.04166666667)
      - x6  * fx_t(0.00138888889)
      + x8  * fx_t(0.00002480158)
      - x10 * fx_t(0.00000027557);
}

// ─────────────────────────────────────────────────────────────────────────────
// Complex multiply: (a+jb)*(c+jd) = (ac-bd) + j(ad+bc)
// ─────────────────────────────────────────────────────────────────────────────
struct cx_t { fx_t re, im; };

static cx_t cx_mul(cx_t a, cx_t b) {
#pragma HLS INLINE
    cx_t r;
    r.re = a.re * b.re - a.im * b.im;
    r.im = a.re * b.im + a.im * b.re;
    return r;
}

static cx_t cx_conj(cx_t a) {
#pragma HLS INLINE
    cx_t r; r.re = a.re; r.im = -a.im; return r;
}

static cx_t cx_add(cx_t a, cx_t b) {
#pragma HLS INLINE
    cx_t r; r.re = a.re + b.re; r.im = a.im + b.im; return r;
}

static cx_t cx_zero() {
#pragma HLS INLINE
    cx_t r; r.re = FX_ZERO; r.im = FX_ZERO; return r;
}

// ─────────────────────────────────────────────────────────────────────────────
// Top-level kernel
// ─────────────────────────────────────────────────────────────────────────────
void kernel_top(
    in0_t  in0[DIM_IN0_0][DIM_IN0_1],
    in1_t  in1,
    out0_t out0[DIM_OUT0_0],
    out1_t out1[DIM_OUT1_0][DIM_OUT1_1],
    out2_t *out2
)
{
#pragma HLS INTERFACE ap_ctrl_hs port=return
#pragma HLS ARRAY_PARTITION variable=in0  complete dim=0
#pragma HLS ARRAY_PARTITION variable=out0 complete dim=0
#pragma HLS ARRAY_PARTITION variable=out1 complete dim=0

    // ── Copy A into working array of cx_t ────────────────────────────────────
    cx_t A[N][N];
    cx_t V[N][N];

INIT_A:
    for (int i = 0; i < N; ++i) {
#pragma HLS UNROLL
        for (int j = 0; j < N; ++j) {
#pragma HLS UNROLL
            A[i][j].re = fx_t(in0[i][j].re);
            A[i][j].im = fx_t(in0[i][j].im);
        }
    }

    // ── V = identity ─────────────────────────────────────────────────────────
INIT_V:
    for (int i = 0; i < N; ++i) {
#pragma HLS UNROLL
        for (int j = 0; j < N; ++j) {
#pragma HLS UNROLL
            V[i][j].re = (i == j) ? FX_ONE : FX_ZERO;
            V[i][j].im = FX_ZERO;
        }
    }

    int    max_iter = (int)(in1);
    out2_t last_z   = (out2_t)0;

ITER_LOOP:
    for (int z = 0; z < 32767; ++z) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=32767 avg=50

        if (z >= max_iter) break;
        last_z = (out2_t)z;

        // ── Find (p,q) with largest |A[i,j]| for i<j ────────────────────────
        fx_t off_max = FX_ZERO;
        int  p = 0, q = 1;

    SEARCH_I:
        for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
        SEARCH_J:
            for (int j = i + 1; j < N; ++j) {
                fx_t abs2 = A[i][j].re * A[i][j].re + A[i][j].im * A[i][j].im;
                if (abs2 > off_max) {
                    off_max = abs2;
                    p = i; q = j;
                }
            }
        }

        // convergence: off_max is |A[p,q]|², compare with thresh²
        if (off_max < fx_t(1e-12)) break;   // 1e-6 squared

        // ── Compute rotation parameters ───────────────────────────────────────
        cx_t a_pq = A[p][q];
        cx_t a_pp = A[p][p];
        cx_t a_qq = A[q][q];

        // |a_pq|
        fx_t abs_apq = fx_sqrt(a_pq.re * a_pq.re + a_pq.im * a_pq.im);

        // theta = 0.5 * atan( 2*|a_pq| / (a_pp.re - a_qq.re) )
        fx_t denom_th = a_pp.re - a_qq.re;
        fx_t theta;
        if (denom_th == FX_ZERO) {
            theta = FX_HALF_PI * FX_HALF;  // π/4
        } else {
            theta = FX_HALF * fx_atan(fx_t(2) * abs_apq / denom_th);
        }

        // phi = -angle(a_pq) = -atan2(a_pq.im, a_pq.re)
        fx_t phi = -fx_atan2(a_pq.im, a_pq.re);

        fx_t cos_th, sin_th;
        fx_sincos(theta, sin_th, cos_th);

        // exp(-j*phi) = cos(phi) - j*sin(phi)
        // exp(+j*phi) = cos(phi) + j*sin(phi)
        fx_t cos_ph, sin_ph;
        fx_sincos(phi, sin_ph, cos_ph);    // sin(phi), cos(phi)

        // U[p,p] =  cos(theta)
        // U[p,q] =  sin(theta)*exp(-j*phi)
        // U[q,p] =  sin(theta)*exp(+j*phi)
        // U[q,q] = -cos(theta)
        cx_t U_pp; U_pp.re =  cos_th;  U_pp.im = FX_ZERO;
        cx_t U_qq; U_qq.re = -cos_th;  U_qq.im = FX_ZERO;
        cx_t U_pq; U_pq.re = sin_th *  cos_ph; U_pq.im = sin_th * (-sin_ph);
        cx_t U_qp; U_qp.re = sin_th *  cos_ph; U_qp.im = sin_th *   sin_ph;

        // ── A ← U† A U  (only rows/cols p,q change) ─────────────────────────
        // Step 1: B = U† A  (conjugate-transpose of U times A)
        // U† has non-trivial entries only at (p,p),(p,q),(q,p),(q,q)
        // (p,p): conj(U_pp)=U_pp*  (q,p): conj(U_pq)
        // (p,q): conj(U_qp)         (q,q): conj(U_qq)

        cx_t Uc_pp = cx_conj(U_pp);
        cx_t Uc_pq = cx_conj(U_qp);  // row p of U† comes from col p of U†=row q of U after conj
        cx_t Uc_qp = cx_conj(U_pq);
        cx_t Uc_qq = cx_conj(U_qq);

        cx_t B[N][N];

        // Rows other than p,q are unchanged
    COPY_B:
        for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
            for (int j = 0; j < N; ++j) {
                if (i == p || i == q) {
                    B[i][j] = cx_zero();
                } else {
                    B[i][j] = A[i][j];
                }
            }
        }

        // Row p of B = Uc_pp * A[p,:] + Uc_pq * A[q,:]
        // Row q of B = Uc_qp * A[p,:] + Uc_qq * A[q,:]
    COMPUTE_B:
        for (int j = 0; j < N; ++j) {
#pragma HLS PIPELINE II=1
            B[p][j] = cx_add(cx_mul(Uc_pp, A[p][j]), cx_mul(Uc_pq, A[q][j]));
            B[q][j] = cx_add(cx_mul(Uc_qp, A[p][j]), cx_mul(Uc_qq, A[q][j]));
        }

        // Step 2: A = B U  (only cols p,q change in each row)
        // Col p of result = B[:,p]*U_pp + B[:,q]*U_qp
        // Col q of result = B[:,p]*U_pq + B[:,q]*U_qq

    COMPUTE_A:
        for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
            cx_t Bip = B[i][p];
            cx_t Biq = B[i][q];
            // columns other than p,q are unchanged (U is identity there)
            // update col p
            A[i][p] = cx_add(cx_mul(Bip, U_pp), cx_mul(Biq, U_qp));
            // update col q
            A[i][q] = cx_add(cx_mul(Bip, U_pq), cx_mul(Biq, U_qq));
            // other columns
            for (int j = 0; j < N; ++j) {
                if (j != p && j != q) A[i][j] = B[i][j];
            }
        }

        // Force off-diagonal elements to zero
        A[p][q] = cx_zero();
        A[q][p] = cx_zero();

        // ── V ← V U  (only cols p,q of V change) ────────────────────────────
    UPDATE_V:
        for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
            cx_t Vip = V[i][p];
            cx_t Viq = V[i][q];
            V[i][p] = cx_add(cx_mul(Vip, U_pp), cx_mul(Viq, U_qp));
            V[i][q] = cx_add(cx_mul(Vip, U_pq), cx_mul(Viq, U_qq));
        }
    }

    // ── Write outputs ────────────────────────────────────────────────────────
WRITE_EVAL:
    for (int i = 0; i < N; ++i) {
#pragma HLS UNROLL
        out0[i].re = out0_scalar_t(A[i][i].re);
        out0[i].im = out0_scalar_t(A[i][i].im);
    }

WRITE_EVEC:
    for (int i = 0; i < N; ++i) {
#pragma HLS UNROLL
        for (int j = 0; j < N; ++j) {
#pragma HLS UNROLL
            out1[i][j].re = out1_scalar_t(V[i][j].re);
            out1[i][j].im = out1_scalar_t(V[i][j].im);
        }
    }

    *out2 = last_z;
}
